import "server-only";
import fs from "node:fs";
import path from "node:path";
import type { BankIndexRow, Difficulty, Question } from "./types";
import type { SectionId } from "./taxonomy";

// Live question bank, generated by `npm run bank:build` (runs automatically before dev/build).
const DIST = path.join(process.cwd(), "content", "bank", "dist");

// Re-read a file when it changes on disk (the bank is rebuilt while the dev server runs).
const cache = new Map<string, { mtime: number; value: unknown }>();
function load<T>(file: string): T {
  const p = path.join(DIST, file);
  const mtime = fs.statSync(p).mtimeMs;
  const hit = cache.get(file);
  if (hit && hit.mtime === mtime) return hit.value as T;
  const value = JSON.parse(fs.readFileSync(p, "utf8")) as T;
  cache.set(file, { mtime, value });
  return value;
}

let byIdFor: Question[] | null = null;
let byId = new Map<string, Question>();
function all(): Question[] {
  const list = load<Question[]>("questions.json");
  if (list !== byIdFor) {
    byId = new Map(list.map((q) => [q.id, q]));
    byIdFor = list;
  }
  return list;
}

/** Compact list of every live question (for the question-bank list view). */
export function getIndex(): BankIndexRow[] {
  return load<BankIndexRow[]>("index.json");
}

/** Full questions by id, in the given order (unknown ids are skipped). */
export function getQuestionsByIds(ids: string[]): Question[] {
  all();
  return ids.map((id) => byId.get(id)).filter((q): q is Question => Boolean(q));
}

export interface QuestionQuery {
  section: SectionId;
  domain: string | "all";
  skill: string | "all";
  difficulty: Difficulty | "all";
  limit: number;
  exclude?: Set<string>;
}

/** Random sample of matching questions (prefers ones not in `exclude`). */
export function sampleQuestions({ section, domain, skill, difficulty, limit, exclude }: QuestionQuery): Question[] {
  const pool = all().filter(
    (q) =>
      q.section === section &&
      (domain === "all" || q.domain === domain) &&
      (skill === "all" || q.skill === skill) &&
      (difficulty === "all" || q.difficulty === difficulty),
  );
  const fresh = exclude?.size ? pool.filter((q) => !exclude.has(q.id)) : pool;
  const picked = take(fresh, limit);
  // Top up with already-seen questions only when the fresh pool runs out.
  if (picked.length < limit && fresh.length < pool.length) {
    picked.push(...take(pool.filter((q) => exclude!.has(q.id)), limit - picked.length));
  }
  return picked;
}

/** Up to n random items (partial Fisher–Yates). */
function take<T>(list: T[], n: number): T[] {
  const a = [...list];
  const count = Math.min(n, a.length);
  for (let i = 0; i < count; i++) {
    const j = i + Math.floor(Math.random() * (a.length - i));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a.slice(0, count);
}
